            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Aller Mehrwert - wie er sich auch verteile, als Gewinn des Kapitalisten, Grundrente, Steuer etc. - ist unbezahlte Arbeit.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Der nächste Weltkrieg wird nicht nur reaktionäre Klassen und Dynastien, er wird auch ganze reaktionäre Völker vom Erdboden verschwinden machen. Und das ist auch ein Fortschritt.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Nichts ist fürchterlicher, als alle Tage von morgens bis abends etwas tun zu müssen, was einem widerstrebt. Und je menschlicher der Arbeiter fühlt, desto mehr muss ihm seine Arbeit verhasst sein, weil er den Zwang, die Zwecklosigkeit für sich selbst fühlt, die in ihr liegen.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Die Beaufsichtigung der Maschinen, das Anknüpfen zerrissener Fäden ist keine Tätigkeit, die das Denken des Arbeiters in Anspruch nimmt, und auf der anderen Seite wieder derart, dass sie den Arbeiter hindert, seinen Geist mit anderen Dingen zu beschäftigen.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Die Demokratie ist proletarisches Prinzip, Prinzip der Massen geworden.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Der Kommunismus ist für uns nicht ein Zustand, der hergestellt werden soll, ein Ideal, wonach die Wirklichkeit sich zu richten haben wird. Wir nennen Kommunismus die wirkliche Bewegung, welche den jetzigen Zustand aufhebt.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Die Gedanken der herrschenden Klasse sind in jeder Epoche die herrschenden Gedanken, d.h. die Klasse, welche die herrschende materielle Macht der Gesellschaft ist, ist zugleich ihre herrschende geistige Macht.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Die Kommunisten wissen zu gut, dass alle Verschwörungen nicht nur nutzlos, sondern sogar schädlich sind.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Ein Gespenst geht um in Europa, das Gespenst des Kommunismus.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Die Geschichte aller bisherigen Gesellschaft ist die Geschichte von Klassenkämpfen.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Die moderne Staatsgewalt ist nur ein Ausschuss, der die gemeinschaftlichen Geschäfte der ganzen Bourgeoisklasse verwaltet.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Der moderne Staat, was auch seine Form, ist eine wesentlich kapitalistische Maschine, Staat der Kapitalisten, der ideelle Gesamtkapitalist.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Der Staat wird nicht abgeschafft, er stirbt ab.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Die Arbeit der Proletarier hat durch die Ausdehnung der Maschinerie und die Teilung der Arbeit allen selbständigen Charakter und damit allen Reiz für den Arbeiter verloren.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "In demselben Maße, in dem die Widerwärtigkeit der Arbeit wächst, nimmt daher der Lohn ab.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Mit der Entwicklung der großen Industrie wird also unter den Füßen der Bourgeoisie die Grundlage selbst hinweggezogen, worauf sie produziert und die Produkte sich aneignet. Sie produziert vor allem ihren eigenen Totengräber. Ihr Untergang und der Sieg des Proletariats sind gleich unvermeidlich.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Kapitalist sein, heißt nicht nur eine rein persönliche, sondern eine gesellschaftliche Stellung in der Produktion einzunehmen.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Die Arbeiter haben kein Vaterland.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Nichts leichter, als dem christlichen Asketismus einen sozialistischen Anstrich zu geben. Hat das Christentum nicht auch gegen das Privateigentum, gegen die Ehe, gegen den Staat geeifert?", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "An die Stelle der alten bürgerlichen Gesellschaft mit ihren Klassen und Klassengegensätzen tritt eine Assoziation, worin die freie Entwicklung eines jeden die Bedingung für die freie Entwicklung aller ist.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Mögen die herrschenden Klassen vor einer kommunistischen Revolution zittern. Die Proletarier haben nichts in ihr zu verlieren als ihre Ketten. Sie haben eine Welt zu gewinnen. Proletarier aller Länder, vereinigt euch!", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Worauf wir nur mit Spinoza antworten können: Ignorantia non est argumentum, die Unwissenheit ist kein Beweisgrund.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Sei endlich einmal etwas weniger gewissenhaft Deinen eignen Sachen gegenüber; es [Das Kapital] ist immer noch viel zu gut für das Lausepublikum. Daß das Ding geschrieben wird und erscheint, ist die Hauptsache; die Schwächen, die Dir auffallen, finden die Esel doch nicht heraus.", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Wir haben hier in England in den letzten zwölf Monaten drei Streiks jüdischer Arbeiter gehabt, und da sollen wir Antisemitismus treiben als Kampf gegen das Kapital?", Author = "Friedrich Engels" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Engels", Text = "Wenn Hegel nicht längst verstorben wäre, er würde sich erhängen.", Author = "Friedrich Engels" },
